import { OpenAIChat } from "../protocols/openai-chat.js";
import { Route } from "../route/client.js";
import { Endpoint } from "../route/endpoint.js";
import { ProviderID } from "../schema/index.js";
import { bearerRouteDefaults, toConfig } from "./settings.js";
export const id = ProviderID.make("togetherai");
const baseURL = "https://api.together.xyz/v1";
export const route = Route.make({
    id: "togetherai-chat",
    provider: id,
    providerMetadataKey: "togetherai",
    protocol: OpenAIChat.protocol,
    endpoint: Endpoint.path("/chat/completions", { baseURL }),
    framing: OpenAIChat.framing,
});
export const routes = [route];
export const configure = (input = {}) => {
    const configured = route.with(bearerRouteDefaults(input, ["TOGETHER_API_KEY", "TOGETHER_AI_API_KEY"], baseURL));
    return {
        id,
        model: (modelID) => configured.model({
            id: modelID,
            compatibility: { maxTokensField: "max_tokens" },
            capabilities: { tools: { strict: false } },
        }),
        configure,
    };
};
export const provider = configure();
export const model = (modelID, settings) => configure(toConfig(settings)).model(modelID);
